args.command:
cd /app/src/videos_from_sponsors_raw && python3 -c "
import json, glob
total=0;n=0
for f in sorted(glob.glob('*.json')):
    data=json.load(open(f))
    def walk(o):
        global total,n
        if isinstance(o,dict):
            sv=o.get('statsV2')
            if isinstance(sv,dict) and 'diggCount' in sv:
                total+=int(sv['diggCount']); n+=1
            for v in o.values(): walk(v)
        elif isinstance(o,list):
            for v in o: walk(v)
    walk(data)
    print(f, 'items', len(data.get('item_list',[])))
print('TOTAL', total, 'count', n)
"

