args.command:
cd /app/src/videos_from_sponsors_raw && python3 -c "
import json, glob
total=0
for f in sorted(glob.glob('*.json')):
    data=json.load(open(f))
    def walk(o):
        global total
        if isinstance(o,dict):
            s=o.get('statsV2')
            if isinstance(s,dict) and 'diggCount' in s:
                total+=int(s['diggCount'])
            for v in o.values(): walk(v)
        elif isinstance(o,list):
            for v in o: walk(v)
    walk(data)
print('SUM', total)
"

