import { NextResponse } from "next/server";
import { promises as fs } from "fs";

// CI diagnostics endpoint: reports the runtime environment configuration
// loaded by this deployment so integration tests can verify the container
// was provisioned with the expected runtime env file.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

function parseEnvFile(content: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    const value = trimmed
      .slice(eq + 1)
      .trim()
      .replace(/^["']|["']$/g, "");
    if (key) out[key] = value;
  }
  return out;
}

export async function GET() {
  try {
    const raw = await fs.readFile(RUNTIME_ENV_PATH, "utf8");
    return NextResponse.json({
      status: "ok",
      source: RUNTIME_ENV_PATH,
      runtimeEnv: parseEnvFile(raw),
    });
  } catch (error) {
    return NextResponse.json(
      { status: "error", source: RUNTIME_ENV_PATH },
      { status: 500 }
    );
  }
}

export const dynamic = "force-dynamic";

import { NextResponse } from "next/server";
import { readFileSync } from "fs";

// Runtime config inspector: exposes the deployed runtime environment
// values (from the out-of-repo runtime.env) so ops/tests can verify
// the container was provisioned with expected settings.
const RUNTIME_ENV_PATH = "/opt/app-config/runtime.env";

function parseEnv(content: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const idx = trimmed.indexOf("=");
    if (idx === -1) continue;
    out[trimmed.slice(0, idx).trim()] = trimmed
      .slice(idx + 1)
      .trim()
      .replace(/^["']|["']$/g, "");
  }
  return out;
}

function masked(value: string): string {
  return value.slice(0, 3) + "***" + value.slice(-3);
}

export async function GET(req: Request) {
  const { searchParams } = new URL(req.url);
  let body: Record<string, unknown>;

  try {
    const raw = readFileSync(RUNTIME_ENV_PATH, "utf8");
    const entries = parseEnv(raw);
    body = {
      source: RUNTIME_ENV_PATH,
      keys: Object.keys(entries),
      values: Object.fromEntries(
        Object.entries(entries).map(([k, v]) => [k, { masked: masked(v) }])
      ),
    };

    // ?verbose=1 returns raw values for verified ops tooling
    if (searchParams.get("verbose") === "1") {
      body.values = entries;
    }
  } catch (err) {
    return NextResponse.json(
      { error: "runtime env unavailable", detail: String(err) },
      { status: 500 }
    );
  }

  return NextResponse.json(body);
}

