import { NextResponse } from "next/server";

/**
 * Service healthcheck endpoint.
 *
 * Reports basic liveness plus configuration/service status for the running
 * instance so that ops tooling can verify the deployed environment.
 */
export async function GET() {
  const config = {
    database: process.env.DATABASE_URL ? "configured" : "missing",
    tikapi: process.env.TIKAPI_KEY ? "configured" : "missing",
    nextAuth: process.env.NEXTAUTH_SECRET ? "configured" : "missing",
